create table public.announcements (
  id integer generated always as identity not null,
  release_id integer,
  kind text not null,
  title text not null,
  body text default ''::text not null,
  items jsonb default '[]'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  created_by text not null,
  updated_at timestamp with time zone,
  updated_by text,
  publish_at timestamp with time zone not null,
  withdrawn_at timestamp with time zone,
  withdrawn_by text,
  constraint announcements_pkey PRIMARY KEY (id),
  constraint announcements_release_id_key UNIQUE (release_id),
  constraint announcements_release_id_fkey FOREIGN KEY (release_id) REFERENCES public.releases(id) ON DELETE CASCADE,
  constraint announcements_body_check CHECK ((length(body) <= 1000)),
  constraint announcements_check CHECK (((release_id IS NULL) = (kind = 'site'::text))),
  constraint announcements_check1 CHECK (((withdrawn_at IS NULL) = (withdrawn_by IS NULL))),
  constraint announcements_created_by_check CHECK (((length(btrim(created_by)) >= 1) AND (length(btrim(created_by)) <= 320))),
  constraint announcements_items_check CHECK (((jsonb_typeof(items) = 'array'::text) AND (jsonb_array_length(items) <= 30))),
  constraint announcements_kind_check CHECK ((kind = ANY (ARRAY['new'::text, 'update'::text, 'site'::text]))),
  constraint announcements_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 160))),
  constraint announcements_updated_by_check CHECK (((updated_by IS NULL) OR ((length(btrim(updated_by)) >= 1) AND (length(btrim(updated_by)) <= 320)))),
  constraint announcements_withdrawn_by_check CHECK (((withdrawn_by IS NULL) OR ((length(btrim(withdrawn_by)) >= 1) AND (length(btrim(withdrawn_by)) <= 320))))
);

CREATE INDEX announcements_recent ON public.announcements USING btree (publish_at DESC, id DESC);

alter table public.announcements enable row level security;
